  "src/App.css": ".app-wrapper {\n  width: 100vw;\n  height: 100vh;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  background-color: #050505;\n  overflow: hidden;\n}\n\n.cabinet-outer {\n  position: relative;\n  width: min(95vw, 55vh);\n  height: min(168vw, 95vh);\n  border-radius: 20px;\n  background: #0f1218;\n  padding: 2.5vmin;\n  box-shadow:\n    -8px -8px 24px rgba(255, 255, 255, 0.02),\n    8px 8px 36px rgba(0, 0, 0, 0.95),\n    inset 0 0 30px rgba(0, 0, 0, 0.9);\n  border: 1px solid rgba(255, 255, 255, 0.01);\n  display: flex;\n  flex-direction: column;\n  overflow: visible;\n  box-sizing: border-box;\n  transition: all 0.2s ease-in-out;\n}\n\n.viewport-container {\n  width: 100%;\n  height: 100%;\n  position: relative;\n  border: 2px solid rgb(22, 22, 26);\n  background: rgb(5, 5, 6);\n  overflow: hidden;\n  border-radius: 12px;\n  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.8);\n  display: flex;\n  flex-direction: column;\n}\n\n.vignette-overlay {\n  position: absolute;\n  inset: 0;\n  background: radial-gradient(circle, transparent 60%, rgba(0, 0, 0, 0.6) 100%);\n  pointer-events: none;\n  z-index: 80;\n  transition: opacity 0.3s ease;\n}\n\n/* Places the telemetry root exactly 44px to the left of the cabinet's bezel */\n#debug-telemetry-root {\n  position: absolute;\n  right: calc(100% + 44px);\n  top: 2.5vmin;\n  width: 250px;\n  z-index: 100;\n}\n\n/* Override inline styles generated by DebugTelemetryOverlay.ts class */\n#debug-telemetry-root > div {\n  position: relative !important;\n  top: 0 !important;\n  left: 0 !important;\n  right: auto !important;\n  width: 100% !important;\n  margin: 0 !important;\n}\n\n/* Hides diagnostic details when displayed space is limited */\n@media (max-width: 1000px) {\n  #debug-telemetry-root {\n    display: none !important;\n  }\n}\n\n@media (max-width: 768px) and (pointer: coarse) {\n  .cabinet-outer {\n    width: 100vw !important;\n    height: 100vh !important;\n    max-width: none !important;\n    max-height: none !important;\n    border-radius: 0 !important;\n    padding: 10px !important;\n    box-shadow: none !important;\n    border: none !important;\n    overflow: hidden !important;\n  }\n\n  .viewport-container {\n    border-radius: 8px;\n  }\n}\n\n/* Web Snag struggle styles */\n.hud-struggle-bar-track {\n  width: 100px;\n  height: 4px;\n  background: #07080b;\n  border: 1px solid #1c202d;\n  border-radius: 2px;\n  overflow: hidden;\n  padding: 1px;\n}\n\n.hud-struggle-bar-fill {\n  height: 100%;\n  background: rgb(239, 68, 68);\n  box-shadow: 0 0 6px rgb(239, 68, 68);\n  border-radius: 1px;\n  transition: width 0.15s ease-out;\n}\n",
  "src/App.tsx": "import { useEffect, useRef } from \"react\";\nimport { bootstrapApplication } from \"./app/bootstrap\";\nimport { HudOverlay } from \"./ui/hud/HudOverlay\";\nimport { ErrorBoundary } from \"./ui/hud/ErrorBoundary\";\nimport { Engine } from \"./core/engine/Engine\";\nimport { Cursor } from \"./ui/cursor/Cursor\";\nimport \"./App.css\";\n\nexport default function App() {\n  const canvasRef = useRef<HTMLCanvasElement | null>(null);\n\n  useEffect(() => {\n    if (!canvasRef.current) return;\n\n    let cancelled = false;\n    let engineInstance: Engine | null = null;\n\n    bootstrapApplication(canvasRef.current).then((engine) => {\n      if (cancelled) {\n        engine.stop();\n        return;\n      }\n      engineInstance = engine;\n      engineInstance.start();\n    });\n\n    return () => {\n      cancelled = true;\n      if (engineInstance) {\n        engineInstance.stop();\n      }\n    };\n  }, []);\n\n  return (\n    <div className=\"app-wrapper\">\n      <div className=\"cabinet-outer\">\n        <div id=\"debug-telemetry-root\" />\n        <div className=\"viewport-container\">\n          <canvas ref={canvasRef} style={{ width: \"100%\", height: \"100%\" }} />\n          <div className=\"vignette-overlay\" />\n          <ErrorBoundary>\n            <HudOverlay />\n          </ErrorBoundary>\n        </div>\n      </div>\n      <Cursor />\n    </div>\n  );\n}\n",
  "src/app/bootstrap.ts": "import { Engine } from \"../core/engine/Engine\";\nimport { useOverlayStore } from \"../ui/hud/hudStore\";\n\nexport async function bootstrapApplication(canvas: HTMLCanvasElement): Promise<Engine> {\n  const overlay = useOverlayStore.getState();\n\n  overlay.setBootStatus(\"READY\");\n  overlay.setAwaitingGesture(true);\n\n  const { CompositionRoot } = await import(\"./compositionRoot\");\n  const root = new CompositionRoot();\n  const engine = root.buildEngine(canvas);\n\n  return engine;\n}\n",
